Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -12,4 +12,74 @@
 </head>
 <body>
 <div id="frame"><canvas id="game" width="1200" height="750" aria-label="Last Call pit lane game"></canvas><div id="hint">WASD / arrows to move · E to interact · Esc to pause</div></div>
 <script>
+(()=>{
+'use strict';
+const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
+const W=1200,H=750,keys=new Set();
+const colors={ink:'#172326',deep:'#10191d',steel:'#304247',line:'#526368',cream:'#f2f0e5',muted:'#a8b8b2',lime:'#d7ef65',orange:'#f18b56',cyan:'#73d5d0',red:'#e75e50'};
+let mode='title',last=0,elapsed=0,score=0,stops=0,misses=0,toast='',toastTime=0,shake=0;
+const player={x:600,y:602,vx:0,vy:0,face:0,carried:null,interactLock:0,anim:0};
+const cars=[{name:'ARIA 07',color:'#f06d4d',number:'07',next:5,stops:0,crew:'#e28e64'},{name:'NOVA 22',color:'#68b6b0',number:'22',next:22,stops:0,crew:'#73c5b6'}];
+let active=null,taskQueue=[],jobIndex=0,jobTime=0,jobLimit=33,carAnim=0,flashes=[],particles=[],clock=0,pausedFrom='';
+const stations={tires:{x:448,y:311,label:'TIRE STACK',icon:'tire'},fuel:{x:750,y:310,label:'FUEL RIG',icon:'fuel'},tools:{x:600,y:290,label:'TOOL WALL',icon:'tools'}};
+const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
+function rr(c,x,y,w,h,r,fill,stroke=null,lw=1){c.beginPath();c.roundRect(x,y,w,h,r);if(fill){c.fillStyle=fill;c.fill()}if(stroke){c.lineWidth=lw;c.strokeStyle=stroke;c.stroke()}}
+function txt(t,x,y,size,color=colors.cream,weight=600,align='left',spacing=0){ctx.font=`${weight} ${size}px ui-sans-serif,system-ui,sans-serif`;ctx.fillStyle=color;ctx.textAlign=align;ctx.textBaseline='middle';if(spacing){ctx.letterSpacing=`${spacing}px`}ctx.fillText(t,x,y);ctx.letterSpacing='0px'}
+function line(x1,y1,x2,y2,color,width=1){ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke()}
+function circle(x,y,r,fill,stroke=null,lw=1){ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.lineWidth=lw;ctx.strokeStyle=stroke;ctx.stroke()}}
+function roundedPanel(x,y,w,h,fill='#10191ddd',stroke='#ffffff22'){rr(ctx,x,y,w,h,10,fill,stroke)}
+function draw(){
+ ctx.clearRect(0,0,W,H);drawWorld();drawGarage();drawStations();drawPitLane();drawCrowd();drawPlayer();drawEffects();drawHUD();
+ if(mode==='title')drawTitle();else if(mode==='paused')drawPause();else if(mode==='over')drawGameOver();
+}
+function drawWorld(){
+ let g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#26363a');g.addColorStop(.52,'#344448');g.addColorStop(1,'#192529');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
+ // concrete texture, kept subtle and deliberate
+ for(let i=0;i<46;i++){let x=(i*173+27)%W,y=(i*97+53)%H;circle(x,y,1+(i%3)*.35,i%2?'#ffffff0b':'#07101312')}
+ // back wall and roof edge
+ ctx.fillStyle='#182427';ctx.fillRect(0,0,W,54);ctx.fillStyle='#415358';ctx.fillRect(0,53,W,4);
+ for(let x=28;x<W;x+=74){line(x,0,x+28,53,'#ffffff08',1)}
+ // floor divisions and drain strips
+ for(let x=23;x<W;x+=120){line(x,70,x,413,'#d7e2d514',1)}
+ ctx.fillStyle='#121b1e';ctx.fillRect(0,414,W,3);ctx.fillStyle='#ffffff12';ctx.fillRect(0,417,W,2);
+ for(let x=18;x<W;x+=48){ctx.fillStyle='#82908d36';ctx.fillRect(x,433,24,2)}
+ // ground marks
+ for(let x=0;x<W;x+=12){ctx.fillStyle=x%24?'#e5e9d8':'#171f21';ctx.fillRect(x,681,12,24)}
+ ctx.fillStyle='#e7e6d9';ctx.fillRect(0,680,W,4);ctx.fillStyle='#121b1e';ctx.fillRect(0,707,W,43);
+ // lane edge lines and pit box
+ line(0,531,W,531,'#e8e7d0',2);line(0,655,W,655,'#e8e7d0',2);
+ ctx.setLineDash([18,16]);line(0,594,W,594,'#e8e7d044',2);ctx.setLineDash([]);
+ // center bay boundary
+ ctx.fillStyle='#d7ef6512';ctx.fillRect(417,423,366,244);ctx.strokeStyle='#d7ef6560';ctx.lineWidth=2;ctx.strokeRect(417,423,366,244);
+ for(let i=0;i<9;i++){ctx.fillStyle=i%2?'#e9eadb':'#151d20';ctx.fillRect(420+i*40,657,40,9)}
+ // side team box lane markings
+ ctx.strokeStyle='#ffffff17';ctx.lineWidth=1;ctx.strokeRect(30,432,330,225);ctx.strokeRect(870,432,300,225);
+}
+function drawGarage(){
+ const bays=[{x:0,w:390,name:'SCUDERIA VELA',accent:'#e66f55',team:'01'}, {x:405,w:390,name:'NORTHSTAR RACING',accent:colors.lime,team:'YOU'}, {x:810,w:390,name:'KITE MOTORSPORT',accent:'#67b7b0',team:'03'}];
+ for(let i=0;i<bays.length;i++){
+  const b=bays[i];
+  ctx.fillStyle=i===1?'#243235':'#222e31';ctx.fillRect(b.x,58,b.w,354);
+  // roof/beam structure
+  ctx.fillStyle='#151f22';ctx.fillRect(b.x,58,b.w,24);
+  ctx.fillStyle=b.accent;ctx.fillRect(b.x,80,b.w,4);
+  for(let px=b.x+18;px<b.x+b.w;px+=130){ctx.fillStyle='#46565a';ctx.fillRect(px,94,7,310);ctx.fillStyle='#182225';ctx.fillRect(px+7,94,4,310)}
+  // workshop back wall
+  ctx.fillStyle='#1c292c';ctx.fillRect(b.x+14,105,b.w-28,119);
+  // wall panel rectangles
+  for(let px=b.x+26;px<b.x+b.w-25;px+=55){ctx.fillStyle='#26373a';ctx.fillRect(px,116,43,94);line(px+7,121,px+7,203,'#ffffff0d',1)}
+  // sign
+  rr(ctx,b.x+22,92,190,28,5,'#10191d','#ffffff18');txt(b.name,b.x+34,106,11,b.accent,800,'left',1.2);
+  // cabinets, work lights
+  for(let k=0;k<3;k++){let x=b.x+38+k*112;rr(ctx,x,229,74,63,4,'#314247','#607174');ctx.fillStyle='#152024';ctx.fillRect(x+6,236,62,4);for(let z=0;z<3;z++)circle(x+14+z*20,270,3,'#f0aa53')}
+  // overhead lamp glow
+  for(let k=0;k<4;k++){ctx.fillStyle='#f6d98b0a';ctx.fillRect(b.x+44+k*86,214,44,3)}
+  // tool counter
+  ctx.fillStyle='#172225';ctx.fillRect(b.x+18,302,b.w-36,7);ctx.fillStyle='#697a78';ctx.fillRect(b.x+18,309,b.w-36,3);
+  // signage plate on back
+  rr(ctx,b.x+b.w-82,92,57,28,4,'#10191d','#ffffff17');txt(b.team,b.x+b.w-53,106,12,b.accent,800,'center',1);
+ }
+ // bright central ceiling light patch
+ let glow=ctx.createRadialGradient(600,280,10,600,280,270);glow.addColorStop(0,'#e7ecc814');glow.addColorStop(1,'#e7ecc800');ctx.fillStyle=glow;ctx.fillRect(330,80,540,310);
+}

input.newString:
function drawStations(){
 // tire racks at the rear of the player's bay
 const t=stations.tires;roundedPanel(t.x-78,t.y-56,156,111,'#182326','#74817c66');txt('01  /  RUBBER',t.x,t.y-45,9,'#aab8ad',800,'center',1.2);
 for(let j=0;j<3;j++){let x=t.x-48+j*48;circle(x,t.y+1,19,'#101618','#66716d',2);circle(x,t.y+1,12,'#273033','#818780',2);circle(x,t.y+1,5,'#11191b','#8b928a',1);line(x-8,t.y-14,x-2,t.y-5,'#59645e',2);line(x+8,t.y+5,x+14,t.y+12,'#59645e',2)}
 rr(ctx,t.x-23,t.y+29,46,16,3,'#222e31','#596968');txt('SOFTS',t.x,t.y+37,8,'#d7ef65',800,'center',.7);
 // fuel station with hose and yellow safety frame
 const f=stations.fuel;roundedPanel(f.x-61,f.y-54,122,110,'#182326','#74817c66');txt('02  /  FUEL',f.x,f.y-43,9,'#aab8ad',800,'center',1.2);
 rr(ctx,f.x-25,f.y-24,50,59,5,'#313e3f','#85918b',2);rr(ctx,f.x-16,f.y-15,32,14,2,'#141d20','#697572');txt('98',f.x,f.y-8,10,colors.lime,800,'center');
 ctx.beginPath();ctx.moveTo(f.x+25,f.y-11);ctx.bezierCurveTo(f.x+51,f.y-8,f.x+45,f.y+28,f.x+28,f.y+25);ctx.strokeStyle='#e7e2c9';ctx.lineWidth=3;ctx.stroke();line(f.x+28,f.y+25,f.x+25,f.y+33,'#f1bb5c',3);
 ctx.fillStyle='#f0bd55';ctx.fillRect(f.x-32,f.y+35,64,5);
 // tool rack marker
 const q=stations.tools;rr(ctx,q.x-79,q.y-37,158,48,4,'#1b272a','#617174');txt('03  /  QUICK SERVICE',q.x,q.y-22,9,'#bac5bb',800,'center',.9);
 for(let j=0;j<5;j++){let x=q.x-51+j*25;line(x,q.y-8,x,q.y+2,j%2?'#e98b5f':'#aab8ad',3);circle(x,q.y+4,3,'#273438')}
 // action labels are drawn in world-space for proximity cues
 if(mode==='playing'){
  const near=nearStation();if(near){let msg=player.carried?`E  ·  DROP ${player.carried.toUpperCase()}`:`E  ·  PICK UP ${near.toUpperCase()}`;prompt(player.x,player.y-34,msg)}
  else if(active&&distance(player.x,player.y,600,542)<77){let need=taskQueue[jobIndex];prompt(600,485,player.carried?`E  ·  FIT ${need?.toUpperCase()||''}`:'E  ·  CHECK CAR')}
 }
}
function drawPitLane(){
 // cars circulating on the lane, with entry/exit fly-bys between service visits
 for(const c of cars){
  if(active===c){drawCar(c,600,542,true);continue}
  if(c.next-elapsed<4&&c.next-elapsed>0){let p=1-(c.next-elapsed)/4;drawCar(c,-100+p*630,594,false)}
  else if(active!==c&&c.stops>0){let x=860+((elapsed*70+c.stops*120)%480);drawCar(c,x,594,false)}
 }
 // service pinstripe / approach arrow
 ctx.fillStyle='#d7ef65';ctx.beginPath();ctx.moveTo(588,470);ctx.lineTo(600,452);ctx.lineTo(612,470);ctx.closePath();ctx.fill();
 if(active){rr(ctx,457,465,286,23,5,'#10191ddd','#d7ef6555');txt(`${active.name}  ·  BOX 01`,600,477,10,colors.lime,800,'center',1.4)}
}
function drawCar(car,x,y,stopped){
 const pulse=stopped?Math.sin(clock*10)*.7:0;ctx.save();ctx.translate(x,y+pulse);
 // shadow
 ctx.fillStyle='#070c0d77';ctx.beginPath();ctx.ellipse(2,5,80,28,0,0,Math.PI*2);ctx.fill();
 // wheels and tires
 for(const wx of [-43,41])for(const wy of [-22,22]){rr(ctx,wx-12,wy-8,25,16,6,'#0b1012','#697371',1);rr(ctx,wx-7,wy-5,15,10,4,'#252e30','#59625e',1)}
 // body silhouette
 ctx.beginPath();ctx.moveTo(-72,-12);ctx.lineTo(-60,-19);ctx.lineTo(-43,-20);ctx.lineTo(-27,-27);ctx.lineTo(21,-26);ctx.lineTo(40,-19);ctx.lineTo(59,-17);ctx.lineTo(72,-9);ctx.lineTo(72,10);ctx.lineTo(57,17);ctx.lineTo(40,19);ctx.lineTo(22,26);ctx.lineTo(-27,26);ctx.lineTo(-43,20);ctx.lineTo(-61,18);ctx.lineTo(-72,10);ctx.closePath();ctx.fillStyle=car.color;ctx.fill();ctx.strokeStyle='#f5e6d377';ctx.lineWidth=1.5;ctx.stroke();
 // nose and rear wing
 ctx.fillStyle='#f4f0e2';ctx.fillRect(61,-12,8,24);ctx.fillStyle='#172326';ctx.fillRect(-68,-22,7,44);
 // racing stripe
 ctx.fillStyle='#f7f4e8';ctx.fillRect(-28,-20,42,40);ctx.fillStyle=car.color;ctx.fillRect(-25,-16,35,32);
 // canopy
 ctx.beginPath();ctx.moveTo(-15,-15);ctx.quadraticCurveTo(10,-19,30,-12);ctx.lineTo(34,12);ctx.quadraticCurveTo(8,19,-15,14);ctx.closePath();ctx.fillStyle='#172a30';ctx.fill();ctx.strokeStyle='#aec2bd';ctx.lineWidth=1;ctx.stroke();
 line(-5,-12,22,10,'#b3d3d2aa',1.5);circle(9,-1,3,'#efc47b');
 // number panel
 rr(ctx,-55,-8,20,16,3,'#f5f0e4');txt(car.number,-45,0,9,'#1b2729',900,'center');
 // headlights
 circle(70,-7,2.4,'#fff5cf');circle(70,7,2.4,'#fff5cf');
 if(stopped){ctx.fillStyle='#f16f55';ctx.fillRect(-73,-17,3,7);ctx.fillRect(-73,10,3,7)}
 ctx.restore();
}
function drawCrew(x,y,shirt,offset=0){
 const bob=Math.sin(clock*3+offset)*1.5;circle(x,y+5+bob,9,'#080e10aa');
 // legs
 ctx.strokeStyle='#182326';ctx.lineWidth=5;ctx.lineCap='round';line(x-3,y+1+bob,x-5,y+10+bob,'#253236',4);line(x+3,y+1+bob,x+5,y+10+bob,'#253236',4);
 circle(x,y-5+bob,7,'#e1b99a');rr(ctx,x-8,y-3+bob,16,12,4,shirt);circle(x,y-6+bob,7,'#d7ad8c');
 ctx.fillStyle='#172225';ctx.beginPath();ctx.arc(x,y-8+bob,7,Math.PI,0);ctx.fill();
}
function drawCrowd(){
 // neighboring crews continue the ballet, never stealing focus from the player's box
 const people=[
  [62,468,'#ce7057',0],[113,506,'#c7c9b7',1],[166,466,'#e08a5f',2],[221,512,'#e5e0cb',3],[286,469,'#cb705a',4],[337,509,'#dad8c7',5],
  [884,474,'#70b5ad',1],[944,510,'#d9ddd0',2],[1001,470,'#6faeaa',3],[1060,509,'#d9ddd0',4],[1120,473,'#6faeaa',5]
 ];for(const p of people)drawCrew(p[0],p[1],p[2],p[3]);
 // empty safety cones and stacked wheels beside other boxes
 for(const x of [386,814]){ctx.fillStyle='#efad53';ctx.beginPath();ctx.moveTo(x,630);ctx.lineTo(x+8,610);ctx.lineTo(x+16,630);ctx.closePath();ctx.fill();line(x+3,624,x+13,624,'#f3e7d0',3)}
}

